T["l3-arr-mod"] = {"version":1,"language":"c","source":"#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\nint main(void) {\n  int arr[] = {1, 2, 3};\n  int *p = arr;\n  *(p + 1) = 9;\n  p++;\n  printf(\"%d %d %d\", arr[1], *p, *(p + 1));\n  return 0;\n}\n","stdin":"","steps":[{"next":4,"frames":[{"fn":"global","vars":{}},{"fn":"main","line":4,"vars":{"arr":"?","p":"?"},"parent":0}]},{"line":4,"next":5,"frames":[{"fn":"global","vars":{}},{"fn":"main","line":5,"vars":{"arr":"?","p":"?"},"parent":0}]},{"line":5,"next":6,"frames":[{"fn":"global","vars":{}},{"fn":"main","line":6,"vars":{"arr":[1,2,3],"p":"?"},"parent":0}],"note":"arr holds 1, 2, 3."},{"line":6,"next":7,"frames":[{"fn":"global","vars":{}},{"fn":"main","line":7,"vars":{"arr":[1,2,3],"p":{"to":"arr[0]","frame":1}},"parent":0}],"note":"An array name used as a value is the address of its first element, so p points at arr[0]."},{"line":7,"next":8,"frames":[{"fn":"global","vars":{}},{"fn":"main","line":8,"vars":{"arr":[1,9,3],"p":{"to":"arr[0]","frame":1}},"parent":0}],"note":"p + 1 is the address of arr[1]; writing 9 through it changes arr[1] to 9. p itself does not move."},{"line":8,"next":9,"frames":[{"fn":"global","vars":{}},{"fn":"main","line":9,"vars":{"arr":[1,9,3],"p":{"to":"arr[1]","frame":1}},"parent":0}],"note":"p++ moves the pointer one int forward, so p now points at arr[1]. The array values do not change."},{"line":9,"next":10,"frames":[{"fn":"global","vars":{}},{"fn":"main","line":10,"vars":{"arr":[1,9,3],"p":{"to":"arr[1]","frame":1}},"parent":0}],"out":"9 9 3","note":"arr[1] is 9; *p is also arr[1], so 9; p + 1 now points at arr[2], so *(p + 1) is 3."},{"line":10,"next":11,"frames":[{"fn":"global","vars":{}},{"fn":"main","line":11,"vars":{"arr":[1,9,3],"p":{"to":"arr[1]","frame":1}},"parent":0}]},{"line":11,"frames":[]}],"exit":{"code":0},"truncated":false};
T["l3-arr-ptr"] = {"version":1,"language":"c","source":"#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\nint main(void) {\n  int arr[] = {4, 8, 15, 16};\n  int *q = arr + 2;\n  printf(\"%d %d\", *q, *(q - 1) + 1);\n  return 0;\n}\n","stdin":"","steps":[{"next":4,"frames":[{"fn":"global","vars":{}},{"fn":"main","line":4,"vars":{"arr":"?","q":"?"},"parent":0}]},{"line":4,"next":5,"frames":[{"fn":"global","vars":{}},{"fn":"main","line":5,"vars":{"arr":"?","q":"?"},"parent":0}]},{"line":5,"next":6,"frames":[{"fn":"global","vars":{}},{"fn":"main","line":6,"vars":{"arr":[4,8,15,16],"q":"?"},"parent":0}],"note":"arr holds 4, 8, 15, 16 at indexes 0 to 3."},{"line":6,"next":7,"frames":[{"fn":"global","vars":{}},{"fn":"main","line":7,"vars":{"arr":[4,8,15,16],"q":{"to":"arr[2]","frame":1}},"parent":0}],"note":"arr + 2 is pointer arithmetic: it moves two ints forward from arr[0], so q points at arr[2], not at the number 2."},{"line":7,"next":8,"frames":[{"fn":"global","vars":{}},{"fn":"main","line":8,"vars":{"arr":[4,8,15,16],"q":{"to":"arr[2]","frame":1}},"parent":0}],"out":"15 9","note":"*q reads arr[2] = 15. q - 1 points at arr[1], so *(q - 1) is 8, and + 1 makes 9. The + 1 is outside the brackets, so it adds to the value, not the address."},{"line":8,"next":9,"frames":[{"fn":"global","vars":{}},{"fn":"main","line":9,"vars":{"arr":[4,8,15,16],"q":{"to":"arr[2]","frame":1}},"parent":0}]},{"line":9,"frames":[]}],"exit":{"code":0},"truncated":false};
T["l3-banana-out"] = {"version":1,"language":"c","source":"#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\nint main(void) {\n  int banana = 13;\n  if (++banana - 7){\n     printf(\"Boogy Boogy\");\n  }\n  else{\n     printf(\"Have a nice day\");\n  }\n  return 0;\n}\n","stdin":"","steps":[{"next":5,"frames":[{"fn":"global","vars":{}},{"fn":"main","line":5,"vars":{"banana":"?"},"parent":0}]},{"line":5,"next":6,"frames":[{"fn":"global","vars":{}},{"fn":"main","line":6,"vars":{"banana":13},"parent":0}],"note":"banana starts at 13."},{"line":6,"next":7,"frames":[{"fn":"global","vars":{}},{"fn":"main","line":7,"vars":{"banana":14},"parent":0}],"note":"++banana is a pre-increment: banana becomes 14 first, then 14 - 7 = 7. Any nonzero number counts as true in C, so the if branch runs."},{"line":7,"next":12,"frames":[{"fn":"global","vars":{}},{"fn":"main","line":12,"vars":{"banana":14},"parent":0}],"out":"Boogy Boogy","note":"The if branch prints Boogy Boogy. The else branch is skipped entirely."},{"line":12,"next":13,"frames":[{"fn":"global","vars":{}},{"fn":"main","line":13,"vars":{"banana":14},"parent":0}]},{"line":13,"frames":[]}],"exit":{"code":0},"truncated":false};
