T["l3-predec"] = {"version":1,"language":"c","source":"#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\nint main(void) {\n  int n = 1;\n  if (--n) {\n      n += 5;\n  } else {\n      n -= 5;\n  }\n  printf(\"%d\", n);\n  return 0;\n}\n","stdin":"","steps":[{"next":5,"frames":[{"fn":"global","vars":{}},{"fn":"main","line":5,"vars":{"n":"?"},"parent":0}]},{"line":5,"next":6,"frames":[{"fn":"global","vars":{}},{"fn":"main","line":6,"vars":{"n":1},"parent":0}],"note":"n starts at 1."},{"line":6,"next":9,"frames":[{"fn":"global","vars":{}},{"fn":"main","line":9,"vars":{"n":0},"parent":0}],"note":"--n is a pre-decrement: n drops to 0 first, and the condition uses that new 0. Zero is false in C, so the else branch runs."},{"line":9,"next":11,"frames":[{"fn":"global","vars":{}},{"fn":"main","line":11,"vars":{"n":-5},"parent":0}],"note":"The else branch subtracts 5 from the current n, which is already 0, giving -5."},{"line":11,"next":12,"frames":[{"fn":"global","vars":{}},{"fn":"main","line":12,"vars":{"n":-5},"parent":0}],"out":"-5","note":"Prints n: -5."},{"line":12,"next":13,"frames":[{"fn":"global","vars":{}},{"fn":"main","line":13,"vars":{"n":-5},"parent":0}]},{"line":13,"frames":[]}],"exit":{"code":0},"truncated":false};
